export const getActionGetGroupRoute = createRoute({
  method: 'get',
  path: '/#Action=GetGroup',
  description:
    ' Returns a list of IAM users that are in the specified IAM group. You can paginate the results using the <code>MaxItems</code> and <code>Marker</code> parameters.',
  operationId: 'GET_GetGroup',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      GroupName: z
        .string()
        .regex(/[\w+=,.@-]+/)
        .min(1)
        .max(128)
        .openapi({
          param: {
            name: 'GroupName',
            in: 'query',
            required: true,
            description:
              '<p>The name of the group.</p> <p>This parameter allows (through its <a href="http://wikipedia.org/wiki/regex">regex pattern</a>) a string of characters consisting of upper and lowercase alphanumeric characters with no spaces. You can also include any of the following characters: _+=,.@-</p>',
            schema: { type: 'string', pattern: '[\\w+=,.@-]+', minLength: 1, maxLength: 128 },
          },
        }),
      Marker: z
        .string()
        .regex(/[\u0020-\u00FF]+/)
        .min(1)
        .max(320)
        .exactOptional()
        .openapi({
          param: {
            name: 'Marker',
            in: 'query',
            required: false,
            description:
              'Use this parameter only when paginating results and only after you receive a response indicating that the results are truncated. Set it to the value of the <code>Marker</code> element in the response that you received to indicate where the next call should start.',
            schema: { type: 'string', pattern: '[\\u0020-\\u00FF]+', minLength: 1, maxLength: 320 },
          },
        }),
      MaxItems: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(1000),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'MaxItems',
            in: 'query',
            required: false,
            description:
              '<p>Use this only when paginating results to indicate the maximum number of items you want in the response. If additional items exist beyond the maximum you specify, the <code>IsTruncated</code> response element is <code>true</code>.</p> <p>If you do not include this parameter, the number of items defaults to 100. Note that IAM might return fewer results, even when there are more results available. In that case, the <code>IsTruncated</code> response element returns <code>true</code>, and <code>Marker</code> contains a value to include in the subsequent call that tells the service where to continue from.</p>',
            schema: { type: 'integer', minimum: 1, maximum: 1000 },
          },
        }),
      Action: z
        .literal('GetGroup')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['GetGroup'] },
          },
        }),
      Version: z
        .literal('2010-05-08')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-08'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: GetGroupResponseSchema } } },
    480: {
      description: 'NoSuchEntityException',
      content: { 'text/xml': { schema: NoSuchEntityExceptionSchema } },
    },
    481: {
      description: 'ServiceFailureException',
      content: { 'text/xml': { schema: ServiceFailureExceptionSchema } },
    },
  },
})

