export const getActionUpdateRoleRoute = createRoute({
  method: 'get',
  path: '/#Action=UpdateRole',
  description: 'Updates the description or maximum session duration setting of a role.',
  operationId: 'GET_UpdateRole',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      RoleName: z
        .string()
        .regex(/[\w+=,.@-]+/)
        .min(1)
        .max(64)
        .openapi({
          param: {
            name: 'RoleName',
            in: 'query',
            required: true,
            description: 'The name of the role that you want to modify.',
            schema: { type: 'string', pattern: '[\\w+=,.@-]+', minLength: 1, maxLength: 64 },
          },
        }),
      Description: z
        .string()
        .regex(/[\u0009\u000A\u000D\u0020-\u007E\u00A1-\u00FF]*/)
        .max(1000)
        .exactOptional()
        .openapi({
          param: {
            name: 'Description',
            in: 'query',
            required: false,
            description: 'The new description that you want to apply to the specified role.',
            schema: {
              type: 'string',
              pattern: '[\\u0009\\u000A\\u000D\\u0020-\\u007E\\u00A1-\\u00FF]*',
              maxLength: 1000,
            },
          },
        }),
      MaxSessionDuration: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(3600).max(43200),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'MaxSessionDuration',
            in: 'query',
            required: false,
            description:
              '<p>The maximum session duration (in seconds) that you want to set for the specified role. If you do not specify a value for this setting, the default value of one hour is applied. This setting can have a value from 1 hour to 12 hours.</p> <p>Anyone who assumes the role from the CLI or API can use the <code>DurationSeconds</code> API parameter or the <code>duration-seconds</code> CLI parameter to request a longer session. The <code>MaxSessionDuration</code> setting determines the maximum duration that can be requested using the <code>DurationSeconds</code> parameter. If users don\'t specify a value for the <code>DurationSeconds</code> parameter, their security credentials are valid for one hour by default. This applies when you use the <code>AssumeRole*</code> API operations or the <code>assume-role*</code> CLI operations but does not apply when you use those operations to create a console URL. For more information, see <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_use.html">Using IAM roles</a> in the <i>IAM User Guide</i>.</p>',
            schema: { type: 'integer', minimum: 3600, maximum: 43200 },
          },
        }),
      Action: z
        .literal('UpdateRole')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['UpdateRole'] },
          },
        }),
      Version: z
        .literal('2010-05-08')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-08'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: UpdateRoleResponseSchema } } },
    480: {
      description: 'UnmodifiableEntityException',
      content: { 'text/xml': { schema: UnmodifiableEntityExceptionSchema } },
    },
    481: {
      description: 'NoSuchEntityException',
      content: { 'text/xml': { schema: NoSuchEntityExceptionSchema } },
    },
    482: {
      description: 'ServiceFailureException',
      content: { 'text/xml': { schema: ServiceFailureExceptionSchema } },
    },
  },
})

